using Xunit;

namespace XunitTest;

// R7-C3a, SPEC 8.2.3: a declaration's identity premises form classes whose compared attributes each domain decides; a premise set that
// makes a Refuted identity, a cycle or an unproven attribute is the table's premise error, recorded once in the declaration whose
// premises form it, at its last premise clause with a Type in the class (R7-C3 C3d), in every order, and never again at uses (no
// dependent record at its other clauses or at a use reading the class).
public partial class TypeIdentityTest
{
    private const string Ref3 = "func f<T>(first: ref/i32 during a, mid: ref/i32 during b, second: ref/i32 during c, value: T) -> i32\n";
    private const string CE = "contract C\n    associate E\n";
    private const string Pair3 = "func f<s/W, U, V>(x: s/W, first: ref/i32 during a, u: U, v: V) -> i32\n";
    private const string FlagBlock = "contract Flag\nstruct Either<A, B>\n    var value: A\n    Self is Flag when A is Option<B>, A is Array<B>\n        public func get(self: ref/Self) -> i32 => 1\n";
    private const string NameBlock = "contract Flag\ncontract K2\n    func name(self: ref/Self) -> i32\nstruct Either<A, B>\n";

    [Theory]
    [InlineData(Ref3 + "    T is ref/i32 during a\n    T is ref/i32 during c\n    origin a outlives b\n    origin b outlives c\n    origin c outlives a\n", "")]
    [InlineData(Ref3 + "    T is ref/i32 during a\n    T is ref/i32 during c\n    origin a outlives b\n    origin b outlives c\n", "UnprovenConstraint_Kd@3")]
    [InlineData("func f<T>(value: T) -> i32\n    T is (ref/i32) -> i32\n    T is (ref/i32) -> i32\n", "")]
    [InlineData("func f<T>(value: T) -> i32\n    T is Option<(ref/i32) -> i32>\n    T is Option<(ref/i32) -> i32>\n", "")]
    [InlineData("func f<T, U>(value: T, u: U) -> i32\n    T is (ref/U, ref/i32) -> i32\n    T is (ref/i32, ref/U) -> i32\n", "")]
    [InlineData("func f<T>(value: T) -> i32\n    T is (ref/bool) -> i32\n    T is (ref/i32) -> i32\n", "InvalidConstraint_Kd@3")]
    [InlineData("func f<T>(value: T) -> i32\n    T is (ref/i32) -> i32\n    T is (ref/i32, ref/i32) -> i32\n", "InvalidConstraint_Kd@3")]
    [InlineData("func f<T, U>(value: T, u: U) -> i32\n    T is [4 of U]\n    T is [(2 + 2) of i32]\n", "")]
    [InlineData("func f<T, U>(value: T, u: U) -> i32\n    T is [4 of U]\n    T is [5 of i32]\n", "InvalidConstraint_Kd@3")]
    [InlineData(Pair3 + "    s is ref\n    V is s/U during a\n    V is ref/i32 during a\n", "")]
    [InlineData(Pair3 + "    s is ref or uniq\n    V is s/U during a\n    V is ref/i32 during a\n", "UnprovenConstraint_Kd@4")]
    [InlineData(Pair3 + "    s is owner\n    V is s/U\n    V is Option<i32>\n", "")]
    [InlineData(Pair3 + "    s is owner\n    V is s/U\n    V is ref/i32 during a\n", "")]
    [InlineData(Pair3 + "    s is owner or ref\n    V is s/U\n    V is Option<i32>\n", "MissingOriginBinding_Kd@3 UnprovenConstraint_Kd@4")]
    [InlineData("func f<s/W, U>(x: s/W, u: U) -> i32\n    s is owner\n    U is s/U\n", "")]
    [InlineData("func f<s/W, U>(x: s/W, u: U) -> i32\n    s is owner or ref\n    U is s/U\n", "MissingOriginBinding_Kd@3 UnprovenConstraint_Kd@3")]
    [InlineData("func f<s/W, U>(x: s/W, first: ref/i32 during a, u: U) -> i32\n    s is ref\n    U is s/U during a\n", "InvalidConstraint_Kd@3")]
    public void PremiseErrorsFollowTheIdentityTable(string source, string records)
        => Assert.Equal(records, PremiseRecords(source + "    return 0\n"));

    // Order-free: the classes are a function of the premise set, so each order gives one record, at the last premise clause with a Type
    // in the erroneous class (SPEC 8.2.3's site, R7-C3 C3d: `reaching` names those premises), and no other.
    [Theory]
    [InlineData("    T is (ref/U) -> i32\n", "    T is (ref/i32) -> i32\n", "    V is ref/W during a\n", "    V is ref/i32 during b\n", "cd")]
    [InlineData("    T is ref/i32 during b\n", "    T is X.(K).A\n", "    X.(K).A is ref/U during a\n", "    X is K\n", "abc")]
    public void APremiseErrorIsOneRecordInEveryOrder(string a, string b, string c, string d, string reaching)
    {
        string[] premises = [a, b, c, d];
        var header = premises.Any(static x => x.Contains("X.(K)", StringComparison.Ordinal)) ?
            "contract K\n    associate A\nfunc f<T, X, U>(first: ref/U during a, second: ref/i32 during b, value: T, x: X.(K).A) -> ref/U during a\n" :
            "func f<T, U, V, W>(first: ref/W during a, second: ref/i32 during b, value: T, u: U, v: V) -> i32\n";
        var body = header.StartsWith("contract", StringComparison.Ordinal) ? "    return x\n" : "    return 0\n";
        var line = header.Count(static x => x == '\n');
        foreach (var order in new[] { premises, [d, c, b, a], [b, d, a, c] })
        {
            var site = order.Select((x, i) => reaching.Contains((char)('a' + Array.IndexOf(premises, x)), StringComparison.Ordinal) ? i : -1).Max();
            Assert.Equal($"UnprovenConstraint_Kd@{line + 1 + site}", PremiseRecords(header + string.Concat(order) + body));
        }
    }

    // N4: a use reading an erroneous class rests on the declaration's record, at its last clause reaching the class (two Contracts'
    // clauses form the unproven meet).
    [Fact]
    public void AUseReadingAnErroneousClassRestsOnTheDeclarationsRecord()
        => Assert.Equal("UnprovenConstraint_Kd@14", PremiseRecords(
            "contract K1\n    associate A\n    associate C\n    Self.(K1).A is Option<Self.(K1).C>\n" +
            "contract K2\n    associate B\n    associate D\n    Self.(K2).B is Option<Self.(K2).D>\n" +
            "func f<T, U>(first: ref/U during a, second: ref/i32 during b, c: T.(K1).C, d: T.(K2).D) -> ref/U during a\n" +
            "    T is K1\n    T is K2\n    T.(K1).A is T.(K2).B\n    T.(K1).C is ref/U during a\n    T.(K2).D is ref/i32 during b\n    return c\n"));

    // SPEC 8.8.2: a conditional conformance's conditions are its scope's premises. Their error is the scope's one record; the
    // conformance's own proof judges the conditions as in a valid view, so its target adds no second record.
    [Theory]
    [InlineData("    Self is Flag when A is Option<B>, A is Array<B>\n", "InvalidConstraint_Kd@4")]
    [InlineData("    Self is Flag when A is Option<B>\n", "")]
    [InlineData("    Self is Flag when A is Option<B>, A is Array<B>\n    Self is Mark when A is Option<B>\n", "InvalidConstraint_Kd@4")]
    public void AConditionsPremiseErrorIsOneRecord(string conformances, string records)
        => Assert.Equal(records, PremiseRecords("contract Flag\ncontract Mark\nstruct Either<A, B>\n" + conformances + "    var value: A\n"));

    // SPEC 8.8.2, 8.2.3 (G881b C1): a block member's conditions read its conformance's failure as the conformance's own proof does
    // (ReadFailedDeclaration). A premise error keeps the conformance's context, so a use judges the member's conditions as in a valid
    // view and keeps its own record: Refuted, the member is inapplicable (a call); Unknown, unproven (a requirement it implements). A
    // use of a member whose own declaration failed rests on that record.
    [Theory]
    [InlineData(FlagBlock + "func g(e: ref/Either<Option<i32>, i32>) -> i32\n    return e.get()\n", "InvalidConstraint_Kd@4 NoApplicableOverload_Kd@7")]
    [InlineData(FlagBlock, "InvalidConstraint_Kd@4")]
    [InlineData(NameBlock + "    Self is K2\n    var value: A\n    Self is Flag when A is Option<B>, A is Array<B>\n        public func name(self: ref/Self) -> i32 => 1\n", "InvalidConstraint_Kd@7 UnprovenConstraint_Kd@5")]
    [InlineData(NameBlock + "    var value: A\n    Self is Flag when A is Option<B>\n        public func name(self: ref/Self) -> i32 => 1\n    Self is K2 when A is Option<B>\n", "")]
    [InlineData("contract Has1\ncontract Inner\nstruct Box<T>\n    var v: i32\n    Self is Has1 when T is Inner\n        public func m(self: ref/Self, x: Missing) -> i32 => 1\nfunc g<T>(b: ref/Box<T>) -> i32\n    T is Inner\n    return b.m(0)\n", "UnresolvedBinding_Kd@6")]
    public void AConditionalMembersConditionsReadItsConformanceAsItsOwnProof(string source, string records)
        => Assert.Equal(records, PremiseRecords(source));

    // R7-C2e2-2, SPEC 8.2.3: two identity premises of one projection to different complete Types are the table's premise error like
    // any other: one record in the declaration whose premises form it, at its last clause reaching the class (R7-C3 C3d), and none at the
    // clauses' projections or at a use. The forms: a
    // function (the Contract before or after it, two or three premises), a struct, a Contract's own clauses, a requirement the premise
    // `T is D` supplies against a written one, a nested projection, fixed arrays of different lengths, and the projection used in the
    // signature and the body. Each with its valid twin.
    [Theory]
    [InlineData(CE + "func f<T>(v: T)\n    T is C\n    T.(C).E is i32\n    T.(C).E is i32\n    ()\n", "")]
    [InlineData(CE + "func f<T>(v: T)\n    T is C\n    T.(C).E is i32\n    T.(C).E is string\n    ()\n", "InvalidConstraint_Kd@6")]
    [InlineData("func f<T>(v: T)\n    T is C\n    T.(C).E is string\n    T.(C).E is i32\n    ()\n" + CE, "InvalidConstraint_Kd@4")]
    [InlineData(CE + "func f<T>(v: T)\n    T is C\n    T.(C).E is i32\n    T.(C).E is i32\n    T.(C).E is string\n    ()\n", "InvalidConstraint_Kd@7")]
    [InlineData(CE + "struct S<T>\n    T is C\n    T.(C).E is i32\n    T.(C).E is i32\n    var v: T\n", "")]
    [InlineData(CE + "struct S<T>\n    T is C\n    T.(C).E is i32\n    T.(C).E is string\n    var v: T\n", "InvalidConstraint_Kd@6")]
    [InlineData("contract D\n    associate E\n    Self.(D).E is i32\n    Self.(D).E is i32\n", "")]
    [InlineData("contract D\n    associate E\n    Self.(D).E is i32\n    Self.(D).E is string\n", "InvalidConstraint_Kd@4")]
    [InlineData("contract D\n    associate E is i32\nfunc f<T>(v: T)\n    T is D\n    T.(D).E is i32\n    ()\n", "")]
    [InlineData("contract D\n    associate E is i32\nfunc f<T>(v: T)\n    T is D\n    T.(D).E is string\n    ()\n", "InvalidConstraint_Kd@5")]
    [InlineData(CE + "contract D\n    associate F\nfunc f<T>(v: T)\n    T is C\n    T.(C).E is D\n    T.(C).E.(D).F is i32\n    T.(C).E.(D).F is i32\n    ()\n", "")]
    [InlineData(CE + "contract D\n    associate F\nfunc f<T>(v: T)\n    T is C\n    T.(C).E is D\n    T.(C).E.(D).F is i32\n    T.(C).E.(D).F is string\n    ()\n", "InvalidConstraint_Kd@9")]
    [InlineData(CE + "func f<T>(v: T)\n    T is C\n    T.(C).E is [(2 + 2) of i32]\n    T.(C).E is [4 of i32]\n    ()\n", "")]
    [InlineData(CE + "func f<T>(v: T)\n    T is C\n    T.(C).E is [4 of i32]\n    T.(C).E is [5 of i32]\n    ()\n", "InvalidConstraint_Kd@6")]
    [InlineData(CE + "func f<T>(v: T.(C).E) -> i32\n    T is C\n    T.(C).E is i32\n    T.(C).E is i32\n    return v\n", "")]
    [InlineData(CE + "func f<T>(v: T.(C).E) -> i32\n    T is C\n    T.(C).E is i32\n    T.(C).E is string\n    return v\n", "InvalidConstraint_Kd@6")]
    public void AProjectionsPremiseErrorIsOneRecordAtItsDeclaration(string source, string records)
        => Assert.Equal(records, PremiseRecords(source));

    // PLAN G925 (SPEC 8.1.1, 8.1.2, 8.2.3): the original `s/T` is the pair row's application of `s` to its target, read as every pair
    // layer is: it meets every form by the pair row, its target is a proper part (Cycles), and its conditional slot is an Origin only
    // in its admitted borrow cases. The coverage table's premise rows and the design review's twins, each at its SPEC label: valid
    // accepted, a Proof row's UnprovenConstraint_Kd and a Language row's InvalidConstraint_Kd at the declaration's last premise clause
    // reaching the class (R7-C3 C3d); the forms: the
    // original against a constructed Type, another binder's original, its own binder's application or a projection, directly, in a
    // Function parameter or result (nested too), an annotation, Option and Tuple, and cycles through it.
    [Theory]
    [InlineData("a01v-dir", "struct Leaf\n    public var v: i32\n    public init(v: i32) => self.v = v\nstruct Leaf2\n    public var v: i32\n    public init(v: i32) => self.v = v\nfunc f<s/A, T>(x: ref/T)\n    s is obj\n    T is s/Leaf\n    T is obj/Leaf\n    ()\npublic func main() -> ()\n    Console.writeLine(\"ok\")\n", "")]
    [InlineData("a01v-rc", "struct Leaf\n    public var v: i32\n    public init(v: i32) => self.v = v\nstruct Leaf2\n    public var v: i32\n    public init(v: i32) => self.v = v\nfunc f<s/A, T>(x: ref/T)\n    s is rc\n    T is () -> s/Leaf\n    T is () -> rc/Leaf\n    ()\npublic func main() -> ()\n    Console.writeLine(\"ok\")\n", "")]
    [InlineData("a01v-rev", "struct Leaf\n    public var v: i32\n    public init(v: i32) => self.v = v\nstruct Leaf2\n    public var v: i32\n    public init(v: i32) => self.v = v\nfunc f<s/A, T>(x: ref/T)\n    s is obj\n    T is () -> obj/Leaf\n    T is () -> s/Leaf\n    ()\npublic func main() -> ()\n    Console.writeLine(\"ok\")\n", "")]
    [InlineData("a01v", "struct Leaf\n    public var v: i32\n    public init(v: i32) => self.v = v\nstruct Leaf2\n    public var v: i32\n    public init(v: i32) => self.v = v\nfunc f<s/A, T>(x: ref/T)\n    s is obj\n    T is () -> s/Leaf\n    T is () -> obj/Leaf\n    ()\npublic func main() -> ()\n    Console.writeLine(\"ok\")\n", "")]
    [InlineData("a01x", "struct Leaf\n    public var v: i32\n    public init(v: i32) => self.v = v\nstruct Leaf2\n    public var v: i32\n    public init(v: i32) => self.v = v\nfunc f<s/A, T>(x: ref/T)\n    s is obj\n    T is () -> s/Leaf\n    T is () -> rc/Leaf\n    ()\npublic func main() -> ()\n    Console.writeLine(\"ok\")\n", "InvalidConstraint_Kd: T is () -> rc/Leaf")]
    [InlineData("a08x-conc", "struct Leaf\n    public var v: i32\n    public init(v: i32) => self.v = v\nstruct Leaf2\n    public var v: i32\n    public init(v: i32) => self.v = v\nfunc f<T>(x: ref/T)\n    T is (obj/Leaf) -> i32\n    T is (obj/Leaf2) -> i32\n    ()\npublic func main() -> ()\n    Console.writeLine(\"ok\")\n", "InvalidConstraint_Kd: T is (obj/Leaf2) -> i32")]
    [InlineData("a08x-rev", "struct Leaf\n    public var v: i32\n    public init(v: i32) => self.v = v\nstruct Leaf2\n    public var v: i32\n    public init(v: i32) => self.v = v\nfunc f<s/A, T>(x: ref/T)\n    s is obj\n    T is (obj/Leaf2) -> i32\n    T is (s/Leaf) -> i32\n    ()\npublic func main() -> ()\n    Console.writeLine(\"ok\")\n", "InvalidConstraint_Kd: T is (s/Leaf) -> i32")]
    [InlineData("a08x", "struct Leaf\n    public var v: i32\n    public init(v: i32) => self.v = v\nstruct Leaf2\n    public var v: i32\n    public init(v: i32) => self.v = v\nfunc f<s/A, T>(x: ref/T)\n    s is obj\n    T is (s/Leaf) -> i32\n    T is (obj/Leaf2) -> i32\n    ()\npublic func main() -> ()\n    Console.writeLine(\"ok\")\n", "InvalidConstraint_Kd: T is (obj/Leaf2) -> i32")]
    [InlineData("e11v-comp", "struct Leaf\n    public var v: i32\n    public init(v: i32) => self.v = v\nstruct Leaf2\n    public var v: i32\n    public init(v: i32) => self.v = v\nfunc f<s/A, T, U>(x: ref/T)\n    s is ref\n    T is (s/A) -> i32\n    T is (s/A) -> U\n    ()\npublic func main() -> ()\n    Console.writeLine(\"ok\")\n", "")]
    [InlineData("e11v-owner", "struct Leaf\n    public var v: i32\n    public init(v: i32) => self.v = v\nstruct Leaf2\n    public var v: i32\n    public init(v: i32) => self.v = v\nfunc f<s/A, T>(x: ref/T)\n    s is owner\n    T is (s/A) -> i32\n    T is (Leaf) -> i32\n    ()\npublic func main() -> ()\n    Console.writeLine(\"ok\")\n", "")]
    [InlineData("e11x-body", "struct Leaf\n    public var v: i32\n    public init(v: i32) => self.v = v\nstruct Leaf2\n    public var v: i32\n    public init(v: i32) => self.v = v\nfunc f<s/A, T>(x: ref/T, y: ref/A) -> i32\n    s is ref\n    T is (s/A) -> i32\n    T is (ref/Leaf during static) -> i32\n    return y.v\npublic func main() -> ()\n    Console.writeLine(\"ok\")\n", "UnprovenConstraint_Kd: T is (ref/Leaf during static) -> i32 | UnresolvedBinding_Kd: return y.v")]
    [InlineData("e11x-dir", "struct Leaf\n    public var v: i32\n    public init(v: i32) => self.v = v\nstruct Leaf2\n    public var v: i32\n    public init(v: i32) => self.v = v\nfunc f<s/A, T>(x: ref/T)\n    s is ref\n    T is s/A\n    T is ref/Leaf during static\n    ()\npublic func main() -> ()\n    Console.writeLine(\"ok\")\n", "UnprovenConstraint_Kd: T is ref/Leaf during static")]
