    [InlineData("e11x-quant", "struct Leaf\n    public var v: i32\n    public init(v: i32) => self.v = v\nstruct Leaf2\n    public var v: i32\n    public init(v: i32) => self.v = v\nfunc f<s/A, T>(x: ref/T)\n    s is ref\n    T is (s/A) -> i32\n    T is (ref/Leaf) -> i32\n    ()\npublic func main() -> ()\n    Console.writeLine(\"ok\")\n", "InvalidConstraint_Kd: T is (ref/Leaf) -> i32")]
